def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty.")

    # Select solution with highest combined normalized marginal potential for both objectives
    max_obj1 = max(obj[0] for _, obj in archive)
    max_obj2 = max(obj[1] for _, obj in archive)
    if max_obj1 == 0 or max_obj2 == 0:
        base_solution = archive[0][0].copy()
    else:
        base_solution = max(archive, key=lambda x: (x[1][0] / max_obj1 + x[1][1] / max_obj2))[0].copy()

    new_solution = base_solution.copy()
    current_weight = np.sum(weight_lst[new_solution == 1])

    # Calculate adaptive marginal gains for both objectives
    marginal_gain1 = value1_lst / (weight_lst + 1e-10)
    marginal_gain2 = value2_lst / (weight_lst + 1e-10)
    combined_marginal = marginal_gain1 + marginal_gain2

    # Phase 1: Probabilistic hybrid mutation (80% flips, 20% swaps)
    if random.random() < 0.8:
        # Flip-based mutation - prioritize items with high combined marginal gain
        sorted_indices = np.argsort(-combined_marginal)
        for idx in sorted_indices[:max(1, len(weight_lst)//10)]:
            if new_solution[idx] == 1:
                if current_weight - weight_lst[idx] >= 0:
                    new_solution[idx] = 0
                    current_weight -= weight_lst[idx]
            else:
                if current_weight + weight_lst[idx] <= capacity:
                    new_solution[idx] = 1
                    current_weight += weight_lst[idx]
    else:
        # Swap-based mutation - exchange high-marginal items with low-marginal ones
        high_marginal = np.argsort(-combined_marginal)[:len(weight_lst)//2]
        low_marginal = np.argsort(combined_marginal)[:len(weight_lst)//2]

        for h in high_marginal:
            for l in low_marginal:
                if new_solution[h] == 1 and new_solution[l] == 0:
                    new_weight = current_weight - weight_lst[h] + weight_lst[l]
                    if new_weight <= capacity:
                        new_solution[h], new_solution[l] = 0, 1
                        current_weight = new_weight
                        break
            else:
                continue
            break

    # Phase 2: Dynamic feasibility check and repair
    if np.sum(weight_lst[new_solution == 1]) > capacity:
        # Greedy removal of lowest marginal items to restore feasibility
        sorted_indices = np.argsort(combined_marginal)
        for idx in sorted_indices:
            if new_solution[idx] == 1:
                new_solution[idx] = 0
                if np.sum(weight_lst[new_solution == 1]) <= capacity:
                    break

    # Phase 3: Probabilistic perturbation for exploration
    if random.random() < 0.2:
        # Random flip of a low-marginal item to escape local optima
        low_marginal_indices = np.argsort(combined_marginal)[:len(weight_lst)//3]
        idx = random.choice(low_marginal_indices)
        if new_solution[idx] == 1:
            if current_weight - weight_lst[idx] >= 0:
                new_solution[idx] = 0
        else:
            if current_weight + weight_lst[idx] <= capacity:
                new_solution[idx] = 1

    return new_solution

