def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Select solution with highest normalized objective diversity
    selected_idx = 0
    max_diversity = -1

    for i, (solution, objective) in enumerate(archive):
        current_weight = np.sum(weight_lst[solution == 1])
        excluded_items = np.where(solution == 0)[0]
        included_items = np.where(solution == 1)[0]

        # Calculate normalized objectives
        norm_obj1 = objective[0] / np.sum(value1_lst)
        norm_obj2 = objective[1] / np.sum(value2_lst)

        # Calculate objective diversity
        diversity = abs(norm_obj1 - norm_obj2)

        if diversity > max_diversity:
            max_diversity = diversity
            selected_idx = i

    base_solution = archive[selected_idx][0].copy()
    new_solution = base_solution.copy()

    # Hybrid local search with dynamic operations
    current_weight = np.sum(weight_lst[new_solution == 1])
    excluded_items = np.where(new_solution == 0)[0]
    included_items = np.where(new_solution == 1)[0]

    # Calculate marginal contributions
    marginal_value1 = value1_lst - (base_solution * value1_lst)
    marginal_value2 = value2_lst - (base_solution * value2_lst)

    # Dynamic operation selection
    operation_weights = [0.6, 0.3, 0.1]  # flip, swap, perturb
    decision = random.choices(['flip', 'swap', 'perturb'], weights=operation_weights)[0]

    if decision == 'flip':
        # Flip items with highest marginal gain while maintaining feasibility
        marginal_combined = marginal_value1 + marginal_value2
        sorted_indices = np.argsort(-marginal_combined)

        for idx in sorted_indices:
            if base_solution[idx] == 1:
                if current_weight - weight_lst[idx] >= 0:
                    new_solution[idx] = 0
                    current_weight -= weight_lst[idx]
            else:
                if current_weight + weight_lst[idx] <= capacity:
                    new_solution[idx] = 1
                    current_weight += weight_lst[idx]

    elif decision == 'swap':
        # Pareto-aware swaps between high and low marginal items
        pareto_front = []
        for i in range(len(weight_lst)):
            if new_solution[i] == 1:
                pareto_front.append((value1_lst[i], value2_lst[i]))

        # Identify Pareto-dominated items to swap out
        dominated_items = []
        for i in range(len(pareto_front)):
            is_dominated = False
            for j in range(len(pareto_front)):
                if i != j and pareto_front[j][0] >= pareto_front[i][0] and pareto_front[j][1] >= pareto_front[i][1]:
                    is_dominated = True
                    break
            if is_dominated:
                dominated_items.append(np.where((value1_lst == pareto_front[i][0]) & (value2_lst == pareto_front[i][1]))[0][0])

        # Identify non-dominated items to swap in
        non_dominated_items = []
        for i in range(len(weight_lst)):
            if new_solution[i] == 0:
                is_non_dominated = True
                for j in range(len(pareto_front)):
                    if value1_lst[i] <= pareto_front[j][0] and value2_lst[i] <= pareto_front[j][1]:
                        is_non_dominated = False
                        break
                if is_non_dominated:
                    non_dominated_items.append(i)

        # Perform swaps
        for d_item in dominated_items:
            for nd_item in non_dominated_items:
                if current_weight - weight_lst[d_item] + weight_lst[nd_item] <= capacity:
                    new_solution[d_item] = 0
                    new_solution[nd_item] = 1
                    current_weight = current_weight - weight_lst[d_item] + weight_lst[nd_item]
                    break
            else:
                continue
            break

    else:  # perturb
        # Dynamic perturbation based on Pareto dominance
        pareto_score = 0
        if len(included_items) > 0:
            included_values = [(value1_lst[i], value2_lst[i]) for i in included_items]
            pareto_score = sum(1 for i in range(len(included_values)) for j in range(len(included_values))
                             if i != j and included_values[j][0] >= included_values[i][0] and included_values[j][1] >= included_values[i][1])

        perturbation_rate = 0.2 * (1 - min(1, pareto_score / len(included_items) if len(included_items) > 0 else 0))

        if np.random.random() < perturbation_rate:
            candidates = []
            for i in range(len(weight_lst)):
                if new_solution[i] == 1 and (current_weight - weight_lst[i] >= 0):
                    candidates.append(i)
                elif new_solution[i] == 0 and (current_weight + weight_lst[i] <= capacity):
                    candidates.append(i)

            if candidates:
                num_perturb = min(2, len(candidates))
                perturb_items = np.random.choice(candidates, size=num_perturb, replace=False)

                for item in perturb_items:
                    new_solution[item] = 1 - new_solution[item]

    # Feasibility repair
    current_weight = np.sum(weight_lst[new_solution == 1])
    while current_weight > capacity:
        included_items = np.where(new_solution == 1)[0]
        if len(included_items) == 0:
            break

        # Calculate Pareto dominance scores for removal candidates
        included_values = [(value1_lst[i], value2_lst[i]) for i in included_items]
        dominance_scores = np.zeros(len(included_items))

        for i in range(len(included_values)):
            for j in range(len(included_values)):
                if i != j and included_values[j][0] >= included_values[i][0] and included_values[j][1] >= included_values[i][1]:
                    dominance_scores[i] += 1

        # Remove items with highest dominance scores (most Pareto-dominated)
        if np.max(dominance_scores) > 0:
            selected_item = included_items[np.argmax(dominance_scores)]
        else:
            # If all equally non-dominated, remove random item
            selected_item = np.random.choice(included_items)

        new_solution[selected_item] = 0
        current_weight -= weight_lst[selected_item]

    return new_solution
